/**
 * Run-state log (IDEAS.md, priority 2026-08-22): pi-brain owns its audit
 * trail. Every workflow event is appended to
 * `.pi/pi-brain/runs/<runId>.jsonl` — one JSON per line — so outcomes, review
 * findings and token usage survive TUI scrolling, crashes and pi's unflushed
 * session files (two real incidents of lost data, see IDEAS.md).
 *
 * `pi.appendEntry` is still called by the extension for pi-side history, but
 * nothing READS it back: the file here is the source of truth for `/flow log`
 * and future resume mode.
 *
 * Writes are best-effort appendFileSync: a run must never die because its
 * audit trail hit a filesystem error. Such errors are reported once on stderr
 * and the sink degrades to no-op.
 */

import { appendFileSync, mkdirSync, readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import type { WorkflowEvent } from "./ports.ts";

export const runsDir = (repoRoot: string): string => join(repoRoot, ".pi", "pi-brain", "runs");

export const runLogPath = (repoRoot: string, runId: string): string =>
  join(runsDir(repoRoot), `${runId}.jsonl`);

export class RunLog {
  readonly #path: string;
  #broken = false;

  constructor(path: string) {
    this.#path = path;
  }

  static open(repoRoot: string, runId: string): RunLog {
    const log = new RunLog(runLogPath(repoRoot, runId));
    try {
      mkdirSync(runsDir(repoRoot), { recursive: true });
      // Heal a torn final line: a crash mid-append leaves a partial JSON
      // without its newline, and the NEXT append would concatenate onto it,
      // destroying that event too (readRunLog drops the whole merged line).
      // Appending the missing newline first confines the loss to the event
      // that was already being lost when the process died.
      try {
        const raw = readFileSync(log.#path);
        if (raw.length > 0 && raw[raw.length - 1] !== 0x0a) appendFileSync(log.#path, "\n", "utf8");
      } catch {
        // Missing file (first open) or unreadable: the touch below handles creation.
      }
      appendFileSync(log.#path, "", "utf8"); // touch: create even before the first event
    } catch (err) {
      log.#fail(err);
    }
    return log;
  }

  #fail(err: unknown): void {
    if (this.#broken) return;
    this.#broken = true;
    const message = err instanceof Error ? err.message : String(err);
    console.error(`pi-brain: run log unavailable (${this.#path}): ${message}`);
  }

  append(event: WorkflowEvent): void {
    if (this.#broken) return;
    try {
      appendFileSync(this.#path, `${JSON.stringify(event)}\n`, "utf8");
    } catch (err) {
      this.#fail(err);
    }
  }
}

/** All events of a past run, oldest first. Empty when the log does not exist. */
export function readRunLog(repoRoot: string, runId: string): WorkflowEvent[] {
  const path = runLogPath(repoRoot, runId);
  if (!existsSync(path)) return [];
  const events: WorkflowEvent[] = [];
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    try {
      events.push(JSON.parse(trimmed) as WorkflowEvent);
    } catch {
      // A torn final line (crash mid-write) is skipped, not fatal.
    }
  }
  return events;
}

/** Run ids that have a log on disk, newest first (by mtime of the log). */
export function listRunIds(repoRoot: string): string[] {
  const dir = runsDir(repoRoot);
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => name.endsWith(".jsonl"))
    .map((name) => ({
      runId: name.slice(0, -".jsonl".length),
      mtime: statSync(join(dir, name)).mtimeMs,
    }))
    .sort((a, b) => b.mtime - a.mtime)
    .map((entry) => entry.runId);
}

/**
 * Ports the workflow engine talks to. Every one of them has a Pi-backed
 * implementation under `src/pi/` and a fake under `tests/`, so workflows can
 * be run end-to-end with no models and no Pi.
 */

import type { VerifyCommand } from "./verify.ts";

export interface ConfirmQuestion {
  message: string;
  detail?: string;
  defaultValue?: boolean;
}
export interface SelectQuestion {
  message: string;
  options: Array<{ label: string; value: string; description?: string }>;
}
export interface InputQuestion {
  message: string;
  placeholder?: string;
  defaultValue?: string;
}

/** Spec §15 — human-in-the-loop is a first-class primitive. */
export interface HumanInput {
  confirm(q: ConfirmQuestion): Promise<boolean>;
  select(q: SelectQuestion): Promise<string>;
  input(q: InputQuestion): Promise<string>;
  editor(q: { message: string; content: string }): Promise<string>;
  /** Non-blocking status line / operational trace. */
  notify(message: string): void;
}

export interface CommandResult {
  command: string;
  exitCode: number;
  output: string;
}

export interface VerifyRunner {
  run(commands: VerifyCommand[], signal?: AbortSignal): Promise<CommandResult[]>;
}

export interface GitBaseline {
  repoRoot: string;
  branch: string;
  headSha: string;
  /**
   * Commit object capturing the entire working tree at baseline, untracked
   * files included. The diff is snapshot-to-snapshot, so pre-existing dirt
   * cancels out on both sides and only the run's own changes remain.
   */
  baseCommit: string;
  /** Digest of tracked .gitignore files and Git exclude files at baseline. */
  ignoreRulesDigest?: string;
}

export interface GitService {
  baseline(cwd: string): Promise<GitBaseline>;
  diffSince(baseline: GitBaseline): Promise<{
    patch: string;
    files: string[];
    /** Submodules with modified contents — their inner diff is NOT in `patch`. */
    dirtySubmodules: string[];
    /** True when ignore rules changed since this baseline. */
    ignoreRulesChanged?: boolean;
  }>;
}

export interface WorkflowEventSink {
  emit(event: WorkflowEvent): void;
}

export type WorkflowEvent =
  | {
      type: "workflow.started";
      runId: string;
      workflow: string;
      /** User's original request (for resume mode). Optional for backward compatibility. */
      description?: string;
      /** Detected or configured stack at workflow start (for resume mode). Optional for backward compatibility. */
      stack?: { primary: string; frameworks: string[] };
      /** Git baseline snapshot commit (for resume mode diffSince). Optional for backward compatibility. */
      baseline?: string;
      /** Digest of ignore rules at workflow start, for resume-safe concealment detection. */
      ignoreRulesDigest?: string;
    }
  | {
      type: "phase.started";
      runId: string;
      phase: string;
      /** SHA256 of the current patch when a review phase starts (for resume-mode change detection). */
      patchSha?: string;
    }
  | {
      type: "agent.started";
      runId: string;
      role: string;
      model: string;
      /** Skill names routed to this role (visibility/debugging). */
      skills?: string[];
    }
  | {
      type: "agent.completed";
      runId: string;
      role: string;
      /** Token usage of THIS agent call, when the runner reports it. */
      usage?: { input: number; output: number };
    }
  | { type: "agent.waiting_input"; runId: string; role: string; question: string }
  | { type: "command.completed"; runId: string; command: string; exitCode: number }
  | { type: "verification.completed"; runId: string; passed: boolean }
  | {
      type: "review.completed";
      runId: string;
      verdict: string;
      round: number;
      /** Persisted so a crash-reconstructed outcome retains the review. */
      summary?: string;
      files?: string[];
      /** Blocking findings of this round, for persisted post-mortems. */
      issues?: Array<{
        id: string;
        severity: string;
        category: string;
        problem: string;
        /** Optional richer issue fields for better post-mortems. */
        file?: string;
        line?: number;
        recommendation?: string;
      }>;
    }
  | {
      /**
       * Final outcome with everything a post-mortem needs — persisted in the
       * run log so findings survive the TUI (IDEAS.md run-state escalation).
       */
      type: "workflow.outcome";
      runId: string;
      status: string;
      reason?: string;
      summary?: string;
      files?: string[];
      /** Last review of the run, issues included (needs_human/completed). */
      review?: {
        verdict: string;
        summary: string;
        issues: Array<{
          id: string;
          severity: string;
          category: string;
          problem: string;
          file?: string;
          line?: number;
          recommendation?: string;
        }>;
      };
      usage?: Record<string, { input: number; output: number }>;
    }
  | { type: "workflow.completed"; runId: string; status: string }
  | { type: "workflow.failed"; runId: string; error: string }
  | { type: "workflow.resumed"; runId: string; phase: string }
  | {
      /**
       * The spec gate was approved. The hashes freeze the PRD/tasks content the
       * user approved: any later mutation of those files (e.g. by the developer
       * making its own work look conformant) is detected and escalates.
       */
      type: "spec.approved";
      runId: string;
      prdSha: string;
      tasksSha: string;
    };

